        b = coords[j]
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        return (dx * dx + dy * dy) ** 0.5

    customers = [i for i in range(n) if i != depot]

    if coords is None:
        customers.sort(key=lambda i: (-demands[i], i))
    else:
        dx0 = coords[depot][0]
        dy0 = coords[depot][1]

        def key(i):
            x = coords[i][0] - dx0
            y = coords[i][1] - dy0
            if x >= 0 and y >= 0:
                q = 0
            elif x < 0 <= y:
                q = 1
            elif x < 0 and y < 0:
                q = 2
            else:
                q = 3
            s = y / (abs(x) + abs(y) + 1e-12)
            r2 = x * x + y * y
            return (q, s, r2, i)

        customers.sort(key=key)

    routes = []
    cur = []
    load = 0
    for c in customers:
        d = demands[c]
        if cur and load + d > capacity:
            routes.append(cur)
            cur = []
            load = 0
        cur.append(c)
        load += d
    if cur:
        routes.append(cur)

    fixed = []
    for r in routes:
        chunk = []
        load = 0
        for c in r:
            d = demands[c]
            if chunk and load + d > capacity:
                fixed.append(chunk)
                chunk = []
                load = 0
            chunk.append(c)
            load += d
        if chunk:
            fixed.append(chunk)
    routes = fixed

    def route_load(r):
        s = 0
        for c in r:
            s += demands[c]
        return s

    def route_cost(r):
        if not r:
            return 0.0
        t = dist(depot, r[0])
        for i in range(len(r) - 1):
            t += dist(r[i], r[i + 1])
        t += dist(r[-1], depot)
        return t

    def two_opt(r):
        if coords is None or len(r) < 4:
            return r[:]
        best = r[:]
        best_cost = route_cost(best)
        improved = True
        while improved:
            improved = False
            m = len(best)
            for i in range(m - 2):
                for k in range(i + 2, m):
                    if i == 0 and k == m - 1:
                        continue
                    cand = best[:i + 1] + best[i + 1:k + 1][::-1] + best[k + 1:]
                    cst = route_cost(cand)
                    if cst + 1e-12 < best_cost:
                        best = cand
                        best_cost = cst
                        improved = True
                        break
                if improved:
                    break
        return best

    routes = [two_opt(r) for r in routes if r]

    changed = True
    while changed:
        changed = False
        loads = [route_load(r) for r in routes]
        for a in range(len(routes)):
            if changed:
                break
            ra = routes[a]
            if not ra:
                continue
            for idx, c in enumerate(ra):
                dc = demands[c]
                prev_a = depot if idx == 0 else ra[idx - 1]
                next_a = depot if idx == len(ra) - 1 else ra[idx + 1]
                delta_rem = dist(prev_a, next_a) - dist(prev_a, c) - dist(c, next_a)
                for b in range(len(routes)):
                    if a == b:
                        continue
                    if loads[b] + dc > capacity:
                        continue
                    rb = routes[b]
                    best_pos = 0
                    best_ins = None
                    for pos in range(len(rb) + 1):
                        prev_b = depot if pos == 0 else rb[pos - 1]
                        next_b = depot if pos == len(rb) else rb[pos]
                        ins = dist(prev_b, c) + dist(c, next_b) - dist(prev_b, next_b)
                        if best_ins is None or ins < best_ins:
                            best_ins = ins
                            best_pos = pos
                    if delta_rem + best_ins + 1e-12 < 0:
                        new_ra = ra[:idx] + ra[idx + 1:]
                        new_rb = rb[:best_pos] + [c] + rb[best_pos:]
                        routes[a] = new_ra
                        routes[b] = new_rb
                        routes = [r for r in routes if r]
                        routes = [two_opt(r) for r in routes]
                        changed = True
                        break
                if changed:
                    break

    seen = [0] * n
    result = []
    for r in routes:
        rr = []
        load = 0
        for c in r:
            if c == depot or c < 0 or c >= n:
                continue
            if seen[c] == 0 and load + demands[c] <= capacity:
                rr.append(c)
                seen[c] = 1
                load += demands[c]
        if rr:
            result.append(rr)

    missing = [i for i in range(n) if i != depot and seen[i] == 0]
    for c in missing:
        best_r = None
        best_pos = None
        best_delta = None
        for ri, r in enumerate(result):
            if route_load(r) + demands[c] > capacity:
                continue
            for pos in range(len(r) + 1):
                prev_n = depot if pos == 0 else r[pos - 1]
                next_n = depot if pos == len(r) else r[pos]
                delta = dist(prev_n, c) + dist(c, next_n) - dist(prev_n, next_n)
                if best_delta is None or delta < best_delta or (delta == best_delta and (ri, pos) < (best_r, best_pos)):
                    best_delta = delta
                    best_r = ri
                    best_pos = pos
        if best_r is None:
            result.append([c])
        else:
            result[best_r] = result[best_r][:best_pos] + [c] + result[best_r][best_pos:]

    final = []
    for r in result:
        rr = []
        load = 0
        for c in r:
            if c != depot and 0 <= c < n and load + demands[c] <= capacity:
                rr.append(c)
                load += demands[c]
        if rr:
            final.append(rr)

    return final
